template<> struct MarsirLaunchDefault<1> { static constexpr int Block = 256; static constexpr int Elems = 64; };
template<> struct MarsirLaunchDefault<2> { static constexpr int Block = 252; static constexpr int Elems = 28; };
template<> struct MarsirLaunchDefault<3> { static constexpr int Block = 256; static constexpr int Elems = 16; };
template<> struct MarsirLaunchDefault<4> { static constexpr int Block = 256; static constexpr int Elems = 8; };
template<> struct MarsirLaunchDefault<5> { static constexpr int Block = 128; static constexpr int Elems = 2; };
template<> struct MarsirLaunchDefault<6> { static constexpr int Block = 128; static constexpr int Elems = 2; };
